"use strict";(self["webpackChunkyuanhua_wiki"]=self["webpackChunkyuanhua_wiki"]||[]).push([[898],{4517(s,a,n){n.r(a);var i=n(6248);const l={id:"elaina",name:"伊蕾娜",nameSub:"Elaina",nameJp:"伊蕾娜",title:"灰之魔女",series:"魔女之旅",image:i,tags:[{text:"魔法使",cls:"tag-purple"},{text:"旅人",cls:"tag-cyan"},{text:"自恋",cls:"tag-pink"},{text:"天才",cls:"tag-amber"},{text:"女主角",cls:"tag-green"}],info:[{icon:"🎂",label:"生日",value:"10月17日",iconClass:"purple"},{icon:"📏",label:"身高",value:"150cm",iconClass:"pink"},{icon:"🌟",label:"称号",value:"灰之魔女",iconClass:"cyan"},{icon:"🔮",label:"魔法",value:"万能魔法",iconClass:"purple"},{icon:"📖",label:"武器",value:"魔杖",iconClass:"pink"},{icon:"🎤",label:"声优",value:"本渡枫（日）",iconClass:"cyan"},{icon:"📺",label:"所属作品",value:"魔女之旅",iconClass:"purple"},{icon:"👩‍🏫",label:"师父",value:"芙兰",iconClass:"pink"},{icon:"🎯",label:"角色定位",value:"女主角 / 核心角色",iconClass:"cyan"}],tabs:[{key:"personality",label:"性格特点",icon:"💭",tags:["✨ 自信自恋","🌸 善良温柔","💰 现实主义者","🗺️ 自由洒脱"],content:['伊蕾娜是<span class="highlight">灰之魔女</span>，年纪轻轻便获得了最高位魔女的称号。她对自己的外貌和才华有着<span class="highlight-pink">极高的自信</span>，常常会对着镜子自夸，这种<span class="highlight">自恋的性格</span>成为了她最标志性的特征之一。','虽然表面上看起来有些<span class="highlight-pink">自我中心</span>，但伊蕾娜内心其实<span class="highlight">非常善良和温柔</span>。在旅途中，她多次伸出援手帮助遇到的人们，即使有时候会<span class="highlight-pink">保持一定的距离感</span>。','她是一个<span class="highlight">现实主义者</span>，认为旅者不应该过度干涉他人的命运。这种想法让她在面对<span class="highlight-pink">一些无法改变的悲剧时</span>，选择以旁观者的身份记录而不是强行介入。','伊蕾娜对<span class="highlight">旅行有着无比的热爱</span>。她从小就憧憬着《妮可冒险谭》中的世界，长大后便踏上了属于自己的<span class="highlight-pink">旅途</span>。对她来说，旅行本身就是最大的意义。']},{key:"appearance",label:"外貌特征",icon:"👁️",tags:["💇 灰白长发","👁️ 琉璃色眼眸","👗 黑色魔女袍","🧢 宽檐魔女帽"],content:['伊蕾娜拥有一头<span class="highlight">如月光般皎洁的灰白色长发</span>，发丝顺滑飘逸，常常在身后自然垂落。她的发色正是她"灰之魔女"<span class="highlight-pink">称号的由来</span>。','她的眼眸是<span class="highlight">清澈的琉璃色</span>，如同雨后的天空一般纯净透明。这双眼睛在旅途中见证了<span class="highlight-pink">无数的风景与故事</span>，时而流露温柔，时而闪过思索。','她身着<span class="highlight">黑色的魔女长袍</span>，外搭一件带有袖口装饰的外套，头戴一顶<span class="highlight-pink">宽檐魔女帽</span>。这身装扮是她作为魔女的标志，也是她旅途中最可靠的伙伴。','胸前佩戴着<span class="highlight">魔女之证——"星"字胸针</span>，这是最高位魔女的证明。年纪轻轻便获得此等殊荣，足以证明伊蕾娜在<span class="highlight-pink">魔法领域的惊人天赋</span>。']},{key:"background",label:"身份背景",icon:"📖",tags:["🔮 灰之魔女","📚 芙兰的弟子","🗺️ 环游世界的旅人","👑 最年轻最高位魔女"],content:['伊蕾娜自幼便展现出<span class="highlight">惊人的魔法天赋</span>。她偶然得到了一本名为《妮可冒险谭》的书籍，从此便对<span class="highlight-pink">旅行充满了向往</span>。年幼的她便离家，踏上了学习魔法的道路。','她拜<span class="highlight">"星尘魔女"芙兰</span>为师，在芙兰的指导下学习了各种魔法知识。芙兰不仅教会了伊蕾娜<span class="highlight-pink">强大的魔法</span>，更教导了她作为魔女应有的<span class="highlight">处世之道</span>。','年仅十四岁便获得了<span class="highlight">最高位魔女的称号</span>，成为史上最年轻的"灰之魔女"。她的师父芙兰亲自授予了她<span class="highlight-pink">魔女之证和旅行用的宽檐帽</span>，正式承认了她的实力。','此后，伊蕾娜开始了<span class="highlight">环游世界的旅途</span>。她到访了各个国家，遇到了形形色色的人和事。每一个经历都成为她旅行记录中<span class="highlight-pink">珍贵的一页</span>。']},{key:"story",label:"旅途见闻",icon:"📜",tags:["🏰 离开故乡","🌸 花田之国","💔 无法改变的悲剧","📝 旅行记录"],content:['伊蕾娜的旅途从<span class="highlight">离开故乡罗贝塔</span>开始。她向父母告别后，踏上了<span class="highlight-pink">追寻梦想的旅程</span>。虽然心中有些不舍，但她知道这才是自己真正想做的事。','她到访了<span class="highlight">许多奇妙的国家</span>——有将花朵视为珍宝的花田之国，有以谎言为法则的国家，也有因魔法而陷入困境的国家。每一个国家都有着<span class="highlight-pink">自己独特的规则与故事</span>。','旅途中，伊蕾娜也遇到了<span class="highlight">无法改变的悲剧</span>。她深知作为旅者的界限——有时候<span class="highlight-pink">旁观记录比强行介入更加重要</span>。这种取舍让她感到痛苦，但也让她变得更加成熟。','她将一路上的所见所闻<span class="highlight">记录在旅行日记</span>中。这些记录不仅是她个人的回忆，也是<span class="highlight-pink">留给读者的珍贵故事</span>。她的旅途仍在继续，每一天都是新的篇章。'],quote:"我只是个旅人、只是个魔女，仅此而已。既非无所不能，也不可能万事如意。",quoteAuthor:"—— 伊蕾娜"}],abilities:[{icon:"🔮",name:"万能魔法",desc:'伊蕾娜掌握了<span class="highlight">多种属性的魔法</span>，几乎可以应对所有情况。这种全面的能力使她能够在<span class="highlight-pink">各种场合灵活运用</span>，是她最强大的武器。'},{icon:"🛡️",name:"防护魔法",desc:'能够生成<span class="highlight">强大的防护屏障</span>，抵御各种攻击。在旅途中，这层<span class="highlight-pink">屏障是她最可靠的防御</span>，多次帮助她化险为夷。'},{icon:"🧹",name:"飞天扫帚",desc:'魔女标志性的<span class="highlight">飞行工具</span>。伊蕾娜能够熟练操控飞天扫帚，<span class="highlight-pink">在空中自由飞翔</span>，这是她旅途中不可或缺的交通工具。'},{icon:"✨",name:"天才资质",desc:'十四岁便成为<span class="highlight">最高位魔女的天才</span>。她的魔法天赋和学习能力远超常人，任何魔法<span class="highlight-pink">只要学习一次就能掌握</span>，是芙兰口中"百年难得一见的奇才"。'}],relationships:[{icon:"👩‍🏫",name:"芙兰",type:"师父",desc:'"星尘魔女"芙兰，伊蕾娜的<span class="highlight">授业恩师</span>。不仅教会了她强大的魔法，更教导了她作为魔女应有的<span class="highlight-pink">处世之道</span>。芙兰亲手授予了她魔女之证和旅行用的宽檐帽。',cls:"rel-family"},{icon:"📖",name:"妮可",type:"憧憬对象",desc:'《妮可冒险谭》的作者。年幼的伊蕾娜偶然得到这本书，从此<span class="highlight">对旅行充满了向往</span>。妮可的冒险故事是伊蕾娜踏上旅途的<span class="highlight-pink">最初动力</span>。',cls:"rel-other"},{icon:"🏠",name:"父母",type:"家人",desc:'伊蕾娜的父母支持她踏上旅途，虽然<span class="highlight">心中不舍但依然放手</span>。临别时的祝福成为了伊蕾娜旅途中<span class="highlight-pink">最温暖的回忆之一</span>。',cls:"rel-family"}]};n.d(a,["default",0,l])},6248(s,a,n){s.exports=n.p+"assets/img/1.639c1c7d.jpg"}}]);
